{
  "name": "agents-chat-cli",
  "version": "3.52.1",
  "description": "多智能体群聊工具 - 支持 OpenCode/Claude Code/Codex/pi 内核，微信风格聊天界面",
  "main": "desktop/main.js",
  "bin": {
    "agents-chat": "./bin/agents-chat.js"
  },
  "files": [
    "bin",
    "lib",
    "app",
    "scripts",
    ".env.example"
  ],
  "keywords": [
    "ai",
    "agent",
    "chat",
    "multi-agent",
    "opencode",
    "claude",
    "codex"
  ],
  "license": "MIT",
  "author": "iamsamyiok",
  "engines": {
    "node": ">=18.0.0"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/iamsamyiok/agents-chat"
  },
  "bugs": {
    "url": "https://github.com/iamsamyiok/agents-chat/issues"
  },
  "homepage": "https://github.com/iamsamyiok/agents-chat",
  "scripts": {
    "start": "node app/server.js",
    "test": "node --test --test-force-exit \"test/*.test.js\"",
    "build:exe": "node scripts/build-exe.js",
    "desktop:dev": "electron desktop/main.js",
    "desktop:build": "node scripts/build-desktop.js",
    "postinstall": "node scripts/postinstall.js"
  },
  "devDependencies": {
    "electron": "^33.2.0",
    "electron-builder": "^25.1.8"
  },
  "dependencies": {
    "@larksuiteoapi/node-sdk": "^1.73.3",
    "axios": "^1.20.0"
  }
}
